function design(site, analyse) {
  const xs = [0, 4.108, 8.217, 12.325, 16.433, 20.542, 24.65,
              28.758, 32.867, 36.975, 41.083, 45.192, 49.3];

  const chord = [
    "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x8", "CHS219.1x8",
    "CHS244.5x8", "CHS273x10", "CHS323.9x10", "CHS355.6x12.5",
    "CHS406.4x12.5", "CHS457x16"
  ];
  const levels = {
    bottom: chord,
    upper: chord,
    post: [
      "CHS114.3x5", "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x8",
      "CHS219.1x8", "CHS244.5x8", "CHS273x10", "CHS323.9x10",
      "CHS355.6x12.5", "CHS406.4x12.5"
    ],
    diagonal: [
      "CHS76.1x4", "CHS88.9x5", "CHS114.3x5", "CHS139.7x6.3",
      "CHS168.3x6.3", "CHS193.7x8", "CHS219.1x8", "CHS244.5x8",
      "CHS273x10", "CHS323.9x10", "CHS355.6x12.5"
    ],
    deckGirder: [
      "CHS76.1x4", "CHS88.9x5", "CHS114.3x5", "CHS139.7x6.3",
      "CHS168.3x6.3", "CHS193.7x8", "CHS219.1x8", "CHS244.5x8"
    ],
    roofGirder: [
      "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x3.2",
      "CHS60.3x4", "CHS76.1x4", "CHS88.9x5", "CHS114.3x5",
      "CHS139.7x6.3", "CHS168.3x6.3"
    ],
    deckBrace: [
      "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x3.2",
      "CHS60.3x4", "CHS76.1x4", "CHS88.9x5", "CHS114.3x5"
    ],
    roofBrace: [
      "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x3.2",
      "CHS60.3x4", "CHS76.1x4", "CHS88.9x5", "CHS114.3x5"
    ]
  };
  const roles = Object.keys(levels);
  const seed = {
    bottom: 6, upper: 6, post: 7, diagonal: 9,
    deckGirder: 4, roofGirder: 6, deckBrace: 5, roofBrace: 5
  };

  function cloneIndices(src) {
    const out = {};
    for (const k of roles) out[k] = src[k];
    return out;
  }

  function topId(side, i) {
    return "T" + side + i;
  }

  function midId(side, i) {
    return "TM" + side + i;
  }

  function makeDesign(H, idx) {
    const nodes = [];
    const members = [];

    for (const side of ["L", "R"]) {
      const z = side === "L" ? -3.05 : 3.05;
      for (let i = 0; i <= 12; i++) {
        nodes.push({ id: topId(side, i), x: xs[i], y: H, z: z, joint: "pin" });
      }
      for (let i = 0; i < 12; i++) {
        nodes.push({
          id: midId(side, i),
          x: (xs[i] + xs[i + 1]) / 2,
          y: H,
          z: z,
          joint: "pin"
        });
      }
    }

    function add(a, b, role) {
      members.push([a, b, "S460 " + levels[role][idx[role]]]);
    }

    // Lower chords, split upper chords, and vertical posts of the two Pratt trusses.
    for (let i = 0; i < 12; i++) {
      add("L" + i, "L" + (i + 1), "bottom");
      add("R" + i, "R" + (i + 1), "bottom");

      add(topId("L", i), midId("L", i), "upper");
      add(midId("L", i), topId("L", i + 1), "upper");
      add(topId("R", i), midId("R", i), "upper");
      add(midId("R", i), topId("R", i + 1), "upper");
    }
    for (let i = 0; i <= 12; i++) {
      add("L" + i, topId("L", i), "post");
      add("R" + i, topId("R", i), "post");
    }

    // Pratt diagonals rise toward midspan under gravity loading.
    for (let i = 0; i < 12; i++) {
      if (i < 6) {
        add("L" + i, topId("L", i + 1), "diagonal");
        add("R" + i, topId("R", i + 1), "diagonal");
      } else {
        add("L" + (i + 1), topId("L", i), "diagonal");
        add("R" + (i + 1), topId("R", i), "diagonal");
      }
    }

    // Deck cross-girders and triangulation in the deck plane.
    for (let i = 0; i <= 12; i++) add("L" + i, "R" + i, "deckGirder");
    for (let i = 0; i < 12; i++) {
      add("L" + i, "R" + (i + 1), "deckBrace");
      add("R" + i, "L" + (i + 1), "deckBrace");
    }

    // Cross-girders and X-bracing in the roof plane.
    const topPairs = [];
    for (let i = 0; i <= 12; i++) {
      topPairs.push({ l: topId("L", i), r: topId("R", i) });
      if (i < 12) {
        topPairs.push({ l: midId("L", i), r: midId("R", i) });
      }
    }
    for (const p of topPairs) add(p.l, p.r, "roofGirder");
    for (let i = 0; i + 1 < topPairs.length; i++) {
      add(topPairs[i].l, topPairs[i + 1].r, "roofBrace");
      add(topPairs[i].r, topPairs[i + 1].l, "roofBrace");
    }

    return {
      note: "Pinned twin Pratt trusses use triangulated deck and roof planes, with sections selected by analysis.",
      nodes: nodes,
      members: members
    };
  }

  function numberOrNull(x) {
    if (x === undefined || x === null || x === "") return null;
    const n = Number(x);
    return Number.isFinite(n) ? n : null;
  }

  function ratio(a, b) {
    const x = numberOrNull(a);
    const y = numberOrNull(b);
    return x === null || y === null || y <= 0 ? null : x / y;
  }

  function safe(r) {
    if (!r || r.error || r.ok !== true) return false;

    const mu = numberOrNull(r.maxUtil);
    if (mu !== null && mu > 0.60) return false;

    let cr = numberOrNull(r.alphaCrMin);
    if (cr === null) cr = numberOrNull(r.alphaCr);
    if (cr !== null && cr < 5.5) return false;

    const sagRatio = ratio(r.sag, r.sagLimit);
    if (sagRatio !== null && sagRatio > 0.82) return false;

    const swayRatio = ratio(r.sway, r.swayLimit);
    if (swayRatio !== null && swayRatio > 0.82) return false;

    const f = numberOrNull(r.frequency);
    if (f !== null && f < 2.35) return false;

    const fatigue = numberOrNull(r.fatigueWorst);
    if (fatigue !== null && fatigue > 0.78) return false;

    const rob = r.robustness;
    if (rob === false) return false;
    if (rob && typeof rob === "object" &&
        (rob.ok === false || rob.pass === false || rob.passed === false)) return false;

    return true;
  }

  function quality(r) {
    if (!r || r.error) return -1e12;
    let q = r.ok === true ? 100000 : 0;

    const mu = numberOrNull(r.maxUtil);
    if (mu !== null) q -= Math.max(0, mu - 0.50) * 400;

    let cr = numberOrNull(r.alphaCrMin);
    if (cr === null) cr = numberOrNull(r.alphaCr);
    if (cr !== null) q -= Math.max(0, 5.8 - cr) * 60;

    const sr = ratio(r.sag, r.sagLimit);
    if (sr !== null) q -= Math.max(0, sr - 0.75) * 180;

    const wr = ratio(r.sway, r.swayLimit);
    if (wr !== null) q -= Math.max(0, wr - 0.75) * 180;

    const f = numberOrNull(r.frequency);
    if (f !== null) q -= Math.max(0, 2.4 - f) * 120;

    const fatigue = numberOrNull(r.fatigueWorst);
    if (fatigue !== null) q -= Math.max(0, fatigue - 0.70) * 180;

    if (r.robustness === false) q -= 1000;

    const mass = numberOrNull(r.mass);
    if (mass !== null) q -= mass * 0.0001;
    return q;
  }

  let calls = 0;
  const callLimit = 105;
  let bestAny = null;
  let bestSafe = null;

  function remember(rec) {
    if (!bestAny || quality(rec.r) > quality(bestAny.r)) bestAny = rec;
    if (safe(rec.r) &&
        (!bestSafe ||
         numberOrNull(rec.r.mass) < numberOrNull(bestSafe.r.mass))) {
      bestSafe = rec;
    }
  }

  function run(H, idx) {
    if (calls >= callLimit) return null;
    calls++;
    const d = makeDesign(H, idx);
    let r;
    try {
      r = analyse(d);
    } catch (e) {
      r = { error: String(e) };
    }
    const rec = { H: H, idx: cloneIndices(idx), d: d, r: r };
    remember(rec);
    return rec;
  }

  const starts = [];
  for (const H of [5.8, 6.2, 6.6]) {
    const rec = run(H, seed);
    if (rec) starts.push(rec);
  }

  let current = bestSafe;
  if (!current && starts.length) {
    current = starts[0];
    for (const rec of starts) {
      if (quality(rec.r) > quality(current.r)) current = rec;
    }

    // If needed, enlarge one member family at a time, guided by the report.
    for (let round = 0; round < 4 && calls < callLimit && !bestSafe; round++) {
      let nextBest = null;
      let nextSafe = null;
      for (const role of roles) {
        if (calls >= callLimit) break;
        if (current.idx[role] + 1 >= levels[role].length) continue;
        const nextIdx = cloneIndices(current.idx);
        nextIdx[role]++;
        const rec = run(current.H, nextIdx);
        if (!rec) continue;
        if (safe(rec.r)) {
          if (!nextSafe ||
              numberOrNull(rec.r.mass) < numberOrNull(nextSafe.r.mass)) {
            nextSafe = rec;
          }
        } else if (!nextBest || quality(rec.r) > quality(nextBest.r)) {
          nextBest = rec;
        }
      }
      if (nextSafe) {
        current = nextSafe;
        break;
      }
      if (!nextBest || quality(nextBest.r) <= quality(current.r)) break;
      current = nextBest;
    }
  }

  if (bestSafe) {
    current = bestSafe;

    // Greedy coordinate descent while retaining conservative analysis margins.
    for (let pass = 0; pass < 8 && calls < callLimit; pass++) {
      let changed = false;
      for (const role of roles) {
        if (calls >= callLimit) break;
        if (current.idx[role] <= 0) continue;
        const nextIdx = cloneIndices(current.idx);
        nextIdx[role]--;
        const rec = run(current.H, nextIdx);
        if (rec && safe(rec.r)) {
          current = rec;
          changed = true;
        }
      }
      if (!changed) break;
    }
  }

  if (bestSafe) {
    bestSafe.d.note =
      "Pinned twin Pratt trusses use triangulated deck and roof planes, with sections selected by analysis.";
    return bestSafe.d;
  }
  if (bestAny) {
    bestAny.d.note =
      "Pinned twin Pratt trusses use triangulated deck and roof planes, with sections selected by analysis.";
    return bestAny.d;
  }
  return makeDesign(6.2, seed);
}

function design(site, analyse) {
  const xs = [0, 4.108, 8.217, 12.325, 16.433, 20.542, 24.65,
              28.758, 32.867, 36.975, 41.083, 45.192, 49.3];

  const levels = {
    bottom: ["CHS114.3x5", "CHS139.7x6.3", "CHS168.3x6.3",
             "CHS193.7x8", "CHS219.1x8", "CHS244.5x8",
             "CHS273x10", "CHS323.9x10", "CHS355.6x12.5"],
    top: ["CHS114.3x5", "CHS139.7x6.3", "CHS168.3x6.3",
          "CHS193.7x8", "CHS219.1x8", "CHS244.5x8",
          "CHS273x10", "CHS323.9x10", "CHS355.6x12.5"],
    post: ["CHS60.3x4", "CHS76.1x4", "CHS88.9x5", "CHS114.3x5",
           "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x8", "CHS219.1x8"],
    diagonal: ["CHS76.1x4", "CHS88.9x5", "CHS114.3x5",
               "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x8",
               "CHS219.1x8", "CHS244.5x8", "CHS273x10", "CHS323.9x10"],
    deckCross: ["CHS48.3x3.2", "CHS60.3x4", "CHS76.1x4",
                "CHS88.9x5", "CHS114.3x5", "CHS139.7x6.3",
                "CHS168.3x6.3", "CHS193.7x8"],
    roofCross: ["CHS48.3x3.2", "CHS60.3x4", "CHS76.1x4",
                "CHS88.9x5", "CHS114.3x5", "CHS139.7x6.3",
                "CHS168.3x6.3", "CHS193.7x8"],
    deckBrace: ["CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x4",
                "CHS76.1x4", "CHS88.9x5", "CHS114.3x5",
                "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x8",
                "CHS219.1x8"],
    roofBrace: ["CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x4",
                "CHS76.1x4", "CHS88.9x5", "CHS114.3x5",
                "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x8",
                "CHS219.1x8"]
  };
  const roles = Object.keys(levels);

  function clone(ix) {
    const out = {};
    for (const role of roles) out[role] = ix[role];
    return out;
  }

  function makeDesign(H, ix) {
    const nodes = [];
    const joints = {};
    const members = [];
    const topId = (side, i) => "T" + side + i;
    const spec = role => "S460 " + levels[role][ix[role]];

    for (let i = 0; i <= 12; i++) {
      nodes.push({
        id: topId("L", i), x: xs[i], y: H, z: -3.05, joint: "rigid"
      });
      nodes.push({
        id: topId("R", i), x: xs[i], y: H, z: 3.05, joint: "rigid"
      });
      joints["L" + i] = "rigid";
      joints["R" + i] = "rigid";
    }

    function add(a, b, role, pinEnds) {
      if (pinEnds) {
        members.push({ a: a, b: b, spec: spec(role), ends: "pin" });
      } else {
        members.push([a, b, spec(role)]);
      }
    }

    // Rigid-jointed main frames; pinned web members keep the trusses efficient.
    for (const side of ["L", "R"]) {
      for (let i = 0; i < 12; i++) {
        add(side + i, side + (i + 1), "bottom", false);
        add(topId(side, i), topId(side, i + 1), "top", false);

        // Pratt orientation: gravity-load diagonals point down toward midspan.
        if (i < 6) {
          add(topId(side, i), side + (i + 1), "diagonal", true);
        } else {
          add(side + i, topId(side, i + 1), "diagonal", true);
        }
      }
      for (let i = 0; i <= 12; i++) {
        add(side + i, topId(side, i), "post", false);
      }
    }

    // Triangulated deck and roof planes close the longitudinal 3-D load paths.
    for (let i = 0; i <= 12; i++) {
      add("L" + i, "R" + i, "deckCross", false);
      add(topId("L", i), topId("R", i), "roofCross", false);
    }
    for (let i = 0; i < 12; i++) {
      if (i % 2 === 0) {
        add("L" + i, "R" + (i + 1), "deckBrace", true);
        add(topId("L", i), topId("R", i + 1), "roofBrace", true);
      } else {
        add("R" + i, "L" + (i + 1), "deckBrace", true);
        add(topId("R", i), topId("L", i + 1), "roofBrace", true);
      }
    }

    return {
      note: "Rigid main joints remove the transverse sway mechanism; pinned Pratt webs and triangulated deck and roof planes provide the 3-D load path.",
      nodes: nodes,
      joints: joints,
      members: members
    };
  }

  function num(x) {
    if (x === undefined || x === null || x === "") return null;
    const n = Number(x);
    return Number.isFinite(n) ? n : null;
  }

  function ratio(a, b) {
    const x = num(a);
    const y = num(b);
    return x === null || y === null || y <= 0 ? null : x / y;
  }

  function safe(r) {
    if (!r || r.error || r.ok !== true) return false;

    const mu = num(r.maxUtil);
    if (mu !== null && mu > 0.68) return false;

    let cr = num(r.alphaCrMin);
    if (cr === null) cr = num(r.alphaCr);
    if (cr !== null && cr < 5.4) return false;

    const sag = ratio(r.sag, r.sagLimit);
    if (sag !== null && sag > 0.80) return false;

    const sway = ratio(r.sway, r.swayLimit);
    if (sway !== null && sway > 0.80) return false;

    const f = num(r.frequency);
    if (f !== null && f < 2.32) return false;

    const fatigue = num(r.fatigueWorst);
    if (fatigue !== null && fatigue > 0.78) return false;

    const rob = r.robustness;
    if (rob === false) return false;
    if (rob && typeof rob === "object" &&
        (rob.ok === false || rob.pass === false || rob.passed === false)) {
      return false;
    }
    return true;
  }

  function quality(r) {
    if (!r || r.error) return -1e12;
    let q = r.ok === true ? 100000 : 0;

    const mu = num(r.maxUtil);
    if (mu !== null) q -= Math.max(0, mu - 0.50) * 1200;

    let cr = num(r.alphaCrMin);
    if (cr === null) cr = num(r.alphaCr);
    if (cr !== null) q += Math.min(cr, 10) * 25;

    const sag = ratio(r.sag, r.sagLimit);
    if (sag !== null) q -= Math.max(0, sag - 0.70) * 300;

    const sway = ratio(r.sway, r.swayLimit);
    if (sway !== null) q -= Math.max(0, sway - 0.70) * 300;

    const f = num(r.frequency);
    if (f !== null) q += Math.min(f, 4) * 15;

    const fatigue = num(r.fatigueWorst);
    if (fatigue !== null) q -= Math.max(0, fatigue - 0.65) * 300;

    if (r.robustness === false) q -= 100000;
    const mass = num(r.mass);
    if (mass !== null) q -= mass * 0.002;
    if (String(r.failure || "").toLowerCase().includes("mechanism")) q -= 200000;
    return q;
  }

  const callLimit = 100;
  let calls = 0;
  let bestAny = null;
  let bestPass = null;
  let bestSafe = null;

  function massOf(rec) {
    return rec ? num(rec.r.mass) : null;
  }

  function remember(rec) {
    if (!bestAny || quality(rec.r) > quality(bestAny.r)) bestAny = rec;

    const m = massOf(rec);
    if (rec.r && rec.r.ok === true && m !== null &&
        (!bestPass || m < massOf(bestPass))) {
      bestPass = rec;
    }
    if (safe(rec.r) && m !== null &&
        (!bestSafe || m < massOf(bestSafe))) {
      bestSafe = rec;
    }
  }

  function run(H, ix) {
    if (calls >= callLimit) return null;
    calls++;
    const d = makeDesign(H, ix);
    let r;
    try {
      r = analyse(d);
    } catch (e) {
      r = { error: String(e) };
    }
    const rec = { H: H, ix: clone(ix), d: d, r: r };
    remember(rec);
    return rec;
  }

  const small = {
    bottom: 2, top: 3, post: 2, diagonal: 4,
    deckCross: 2, roofCross: 2, deckBrace: 2, roofBrace: 2
  };
  const medium = {
    bottom: 4, top: 4, post: 4, diagonal: 6,
    deckCross: 3, roofCross: 3, deckBrace: 4, roofBrace: 4
  };
  const large = {
    bottom: 6, top: 6, post: 7, diagonal: 8,
    deckCross: 5, roofCross: 5, deckBrace: 7, roofBrace: 7
  };

  const trials = [
    { H: 8.4, ix: small },
    { H: 8.4, ix: medium },
    { H: 9.4, ix: medium },
    { H: 10.0, ix: medium },
    { H: 8.8, ix: large },
    { H: 9.6, ix: large }
  ];
  for (const t of trials) run(t.H, t.ix);

  if (bestSafe) {
    let current = bestSafe;

    // Compare a few truss depths with the current sections.
    for (const H of [7.6, 8.4, 9.2, 10.0]) {
      if (calls >= callLimit) break;
      const rec = run(H, current.ix);
      if (rec && safe(rec.r) && massOf(rec) < massOf(current)) current = rec;
    }
    if (bestSafe && massOf(bestSafe) < massOf(current)) current = bestSafe;

    // Greedily reduce each member family while retaining conservative margins.
    const order = [
      "diagonal", "top", "bottom", "post",
      "deckBrace", "roofBrace", "deckCross", "roofCross"
    ];
    for (let pass = 0; pass < 3 && calls < callLimit; pass++) {
      let changed = false;
      for (const role of order) {
        while (calls < callLimit && current.ix[role] > 0) {
          const nextIx = clone(current.ix);
          nextIx[role]--;
          const rec = run(current.H, nextIx);
          if (rec && safe(rec.r) && massOf(rec) < massOf(current)) {
            current = rec;
            changed = true;
          } else {
            break;
          }
        }
      }
      if (!changed) break;
    }
  } else {
    // If necessary, grow the best analysed candidate toward a passing design.
    let current = bestAny;
    for (let round = 0; round < 6 && current && calls < callLimit; round++) {
      let nextBest = null;
      let nextSafe = null;
      for (const role of roles) {
        if (calls >= callLimit) break;
        if (current.ix[role] + 1 >= levels[role].length) continue;

        const nextIx = clone(current.ix);
        nextIx[role]++;
        const rec = run(current.H, nextIx);
        if (!rec) continue;

        if (safe(rec.r)) {
          if (!nextSafe || massOf(rec) < massOf(nextSafe)) nextSafe = rec;
        } else if (!nextBest || quality(rec.r) > quality(nextBest.r)) {
          nextBest = rec;
        }
      }
      if (nextSafe) break;
      if (!nextBest || quality(nextBest.r) <= quality(current.r)) break;
      current = nextBest;
    }
  }

  if (bestSafe) return bestSafe.d;
  if (bestAny && bestAny.r && bestAny.r.ok === true) return bestAny.d;
  if (bestPass) return bestPass.d;
  if (bestAny) return bestAny.d;
  return makeDesign(8.8, large);
}

function design(site, analyse) {
  const xs = [0, 4.108, 8.217, 12.325, 16.433, 20.542, 24.65,
              28.758, 32.867, 36.975, 41.083, 45.192, 49.3];

  const chordSections = [
    "CHS88.9x5", "CHS114.3x5", "CHS139.7x6.3", "CHS168.3x6.3",
