function design(site, analyse) {
  const xs = [0,4.108,8.217,12.325,16.433,20.542,24.65,28.758,32.867,36.975,41.083,45.192,49.3];
  const L = 49.3;
  const F = 13.5;
  const Y_MIN = 5.35;

  function yArch(i) {
    if (i <= 0 || i >= 12) return 0;
    const x = xs[i];
    let y = F * 4 * x * (L - x) / (L * L);
    if (y < Y_MIN) y = Y_MIN;
    return y;
  }

  function build(p) {
    const nodes = [];
    const members = [];
    const seen = new Set();
    const joints = {};

    function addNode(id, x, y, z, isTop) {
      let joint = "pin";
      if (p.mode >= 2) joint = "rigid";
      else if (p.mode === 1 && isTop) joint = "rigid";
      nodes.push({id:id, x:x, y:y, z:z, joint:joint});
    }

    function addMember(a, b, spec) {
      if (!spec || a === b) return;
      const key = a < b ? (a + "|" + b) : (b + "|" + a);
      if (seen.has(key)) return;
      seen.add(key);
      members.push([a,b,spec]);
    }

    function topNode(side, i) {
      if (i === 0) return side === "L" ? "L0" : "R0";
      if (i === 12) return side === "L" ? "L12" : "R12";
      return (side === "L" ? "AL" : "AR") + i;
    }

    // Arch nodes at every internal deck station, with low end nodes raised to y=5.35.
    for (let i = 1; i <= 11; i++) {
      const y = yArch(i);
      addNode("AL" + i, xs[i], y, -3.05, true);
      addNode("AR" + i, xs[i], y,  3.05, true);
    }

    // Outrigger nodes outside the traffic envelope.
    const yOut = 3.0;
    const zOut = 4.6;
    for (let i = 1; i <= 11; i++) {
      addNode("OL" + i, xs[i], yOut, -zOut, false);
      addNode("OR" + i, xs[i], yOut,  zOut, false);
    }

    if (p.mode >= 2) {
      for (let i = 0; i <= 12; i++) {
        joints["L" + i] = "rigid";
        joints["R" + i] = "rigid";
      }
    }

    // Main arch ribs.
    for (let side = 0; side < 2; side++) {
      const s = side === 0 ? "L" : "R";
      for (let i = 1; i <= 12; i++) {
        addMember(topNode(s, i-1), topNode(s, i), p.arch);
      }
    }

    // Deck edge chords / tie.
    for (let i = 0; i < 12; i++) {
      addMember("L" + i, "L" + (i+1), p.deckChord);
      addMember("R" + i, "R" + (i+1), p.deckChord);
    }

    // Vertical hangers.
    for (let i = 1; i <= 11; i++) {
      addMember("L" + i, topNode("L", i), p.hanger);
      addMember("R" + i, topNode("R", i), p.hanger);
    }

    // Side web diagonals: one per interior panel, making each side a fully triangulated truss.
    for (let i = 2; i <= 11; i++) {
      addMember("L" + (i-1), topNode("L", i), p.sideDiag);
      addMember("R" + (i-1), topNode("R", i), p.sideDiag);
    }

