  base0.mode = 0;
  let r0 = evalD(base0);
  candidates.push({params:base0, r:r0});

  // If the pin version is not comfortably safe, also try an X-braced rigid-top version.
  if (!isSafe(r0, strict)) {
    let base1 = JSON.parse(JSON.stringify(heavy));
    base1.mode = 1;
    let r1 = evalD(base1);
    candidates.push({params:base1, r:r1});

    if (!isSafe(r1, strict) && !isSafe(r1, relaxed)) {
      let base2 = JSON.parse(JSON.stringify(heavy));
      base2.mode = 2;
      let r2 = evalD(base2);
      candidates.push({params:base2, r:r2});
    }
  }

  let chosenBase = candidates[0];
  let bestRank = levelRank(chosenBase.r);
  let bestMass = chosenBase.r && chosenBase.r.mass != null ? chosenBase.r.mass : Infinity;

  for (let i = 1; i < candidates.length; i++) {
    const c = candidates[i];
    const rk = levelRank(c.r);
    const m = c.r && c.r.mass != null ? c.r.mass : Infinity;
    if (rk > bestRank || (rk === bestRank && m < bestMass)) {
      chosenBase = c;
      bestRank = rk;
      bestMass = m;
    }
  }

  let level = fallback;
  if (isSafe(chosenBase.r, strict)) level = strict;
  else if (isSafe(chosenBase.r, relaxed)) level = relaxed;
  else if (isSafe(chosenBase.r, fallback)) level = fallback;

  const opt = optimize(chosenBase.params, chosenBase.r, level, 3);

  let finalParams = opt.params;
  let finalR = opt.r;

  // Never return an unsafe optimized state: revert if anything went wrong.
  if (!finalR || finalR.ok === false || finalR.error || !isSafe(finalR, level)) {
    finalParams = chosenBase.params;
    finalR = chosenBase.r;
  }

  const out = build(finalParams);
  out.note = "Attempt 2: fully triangulated S690 tied arch; vertical hangers, single side-web diagonals, top and deck lateral bracing, and same-side outrigger portals to prevent 3D sway.";
  return out;
}

