    const joints = {};

    function addNode(id, x, y, z) {
      nodes.push({ id: id, x: x, y: y, z: z, joint: p.rigid ? "rigid" : "pin" });
    }

    function addMember(a, b, spec) {
      if (!spec || a === b) return;
      const key = a < b ? (a + "|" + b) : (b + "|" + a);
      if (seen.has(key)) return;
      seen.add(key);
      members.push([a, b, spec]);
    }

    const topY = {};
    for (let i = 1; i <= 11; i++) {
      let y = F * 4 * xs[i] * (Ls - xs[i]) / (Ls * Ls);
      if (y < YMIN) y = YMIN;
      if (y > 16.3) y = 16.3;
      topY[i] = y;
      addNode("TL" + i, xs[i], y, -Ztop);
      addNode("TR" + i, xs[i], y,  Ztop);
    }

    if (p.rigid) {
      for (let i = 0; i <= 12; i++) {
        joints["L" + i] = "rigid";
        joints["R" + i] = "rigid";
      }
    }

    // Top chords / arch ribs.
    for (let side = 0; side < 2; side++) {
      const s = side === 0 ? "L" : "R";
      const t = side === 0 ? "TL" : "TR";
      let prev = s + "0";
      for (let i = 1; i <= 11; i++) {
        const cur = t + i;
        const seg = i - 1;
        const spec = (seg < 2 || seg >= 10) ? p.archEnd : p.archMid;
        addMember(prev, cur, spec);
        prev = cur;
      }
      addMember(prev, s + "12", p.archEnd);
    }

    // Continuous deck edge chords / ties.
    for (let i = 0; i < 12; i++) {
      addMember("L" + i, "L" + (i + 1), p.chord);
      addMember("R" + i, "R" + (i + 1), p.chord);
    }

    // Outward-sloping hangers.
    for (let i = 1; i <= 11; i++) {
      addMember("L" + i, "TL" + i, p.hanger);
      addMember("R" + i, "TR" + i, p.hanger);
    }

    // Side-web diagonals, completing every longitudinal bay.
    for (let i = 1; i <= 10; i++) {
      const spec = (i <= 3 || i >= 8) ? p.sideEnd : p.sideMid;
      addMember("L" + i, "TL" + (i + 1), spec);
      addMember("R" + i, "TR" + (i + 1), spec);
    }

    // Transverse deck beams.
    for (let i = 0; i <= 12; i++) {
      addMember("L" + i, "R" + i, p.deckCross);
    }

    // Transverse top beams above the traffic envelope.
    for (let i = 1; i <= 11; i++) {
      addMember("TL" + i, "TR" + i, p.topCross);
    }

    // Bottom lateral bracing in every bay.
    for (let i = 0; i < 12; i++) {
      addMember("L" + i, "R" + (i + 1), p.bottomBrace);
    }

    // Top lateral bracing in every internal bay.
    for (let i = 1; i <= 10; i++) {
      addMember("TL" + i, "TR" + (i + 1), p.topBrace);
    }

    return { note: "", nodes: nodes, joints: joints, members: members };
  }

  let calls = 0;
  const MAXCALLS = 360;
  const cache = new Map();

  function evalD(params) {
    const key = JSON.stringify(params);
    if (cache.has(key)) return cache.get(key);
    if (calls >= MAXCALLS) return null;
    calls++;
    let r;
