    if (r.sag != null && r.sagLimit != null && r.sag > lv.sag * r.sagLimit) return false;
    if (r.sway != null && r.swayLimit != null && r.sway > lv.sway * r.swayLimit) return false;
    if (r.fatigueWorst != null && r.fatigueWorst > lv.fatigue) return false;
    if (r.robustness === false) return false;
    return true;
  }

  function optimize(start, lv, order) {
    let cur = JSON.parse(JSON.stringify(start));
    let curR = evalD(cur);
    if (!curR || curR.error || curR.ok === false || !isSafe(curR, lv)) return null;

    for (let pass = 0; pass < 3; pass++) {
      let changed = false;

      for (let gi = 0; gi < order.length; gi++) {
        const g = order[gi];
        const list = opts[g];
        if (!list) continue;

        let bestSpec = cur[g];
        let bestR = curR;

        for (let oi = 0; oi < list.length; oi++) {
          const spec = list[oi];
          if (spec === cur[g]) break;

          const trial = JSON.parse(JSON.stringify(cur));
          trial[g] = spec;
          const rr = evalD(trial);

          if (rr && !rr.error && rr.ok !== false && isSafe(rr, lv)) {
            bestSpec = spec;
            bestR = rr;
            break;
          }
        }

        if (bestSpec !== cur[g]) {
          cur[g] = bestSpec;
          curR = bestR;
          changed = true;
        }
      }

      if (!changed) break;
    }

    return { params: cur, r: curR };
  }

  const orders = [
    ["archEnd","archMid","chord","sideEnd","sideMid","deckCross","hanger","topCross","bottomBrace","topBrace"],
    ["chord","deckCross","archEnd","sideEnd","archMid","sideMid","hanger","bottomBrace","topBrace","topCross"],
    ["sideEnd","sideMid","archEnd","archMid","chord","deckCross","bottomBrace","topBrace","topCross","hanger"]
  ];

  const levels = [
    { util: 0.55, alpha: 9.0, freq: 2.45, sag: 0.68, sway: 0.68, fatigue: 0.68 },
    { util: 0.65, alpha: 7.0, freq: 2.30, sag: 0.85, sway: 0.85, fatigue: 0.85 },
    { util: 0.78, alpha: 5.0, freq: 2.15, sag: 0.98, sway: 0.98, fatigue: 0.98 }
  ];

  function runLevel(rigid, lv) {
    const start = JSON.parse(JSON.stringify(heavy));
    start.rigid = rigid;

    const r0 = evalD(start);
    if (!r0 || r0.error || r0.ok === false || !isSafe(r0, lv)) return null;

    let best = null;

    for (let oi = 0; oi < orders.length; oi++) {
      if (calls >= MAXCALLS - 8) break;
      const res = optimize(start, lv, orders[oi]);
      if (res && res.r && isSafe(res.r, lv)) {
        if (!best || res.r.mass < best.r.mass) best = res;
      }
    }

    return best;
  }

  let finalRes = null;

  for (let li = 0; li < levels.length; li++) {
    const lv = levels[li];
    finalRes = runLevel(false, lv);
    if (!finalRes) finalRes = runLevel(true, lv);
    if (finalRes) break;
  }

  if (!finalRes) {
    let start = JSON.parse(JSON.stringify(heavy));
    start.rigid = false;
    let r = evalD(start);
    if (r && !r.error && r.ok !== false) {
      finalRes = { params: start, r: r };
    } else {
      start.rigid = true;
      r = evalD(start);
      finalRes = { params: start, r: r };
    }
  }

  const out = build(finalRes.params);
  out.note = "Attempt 3: fully triangulated S690 tied arch with outward-sloping hangers to z=±5.6, continuous deck ties, and complete top and bottom lateral bracing in every bay; sized with conservative built-unit margins.";
  return out;
}

