  ];

  let p = Object.assign({}, heavy);
  let chosenLevel = null;
  for (const lv of levels) {
    const r = evalD(p);
    if (r && isSafe(r, lv)) {
      chosenLevel = lv;
      break;
    }
  }
  if (!chosenLevel) {
    // Return heavy fallback; hopefully still valid under nominal.
    return build(p);
  }

  // ---------- greedy reduction ----------
  const groups = [
    "topChord","midChord","bottomChord","deckChord",
    "upperDiag","lowerDiag",
    "verticalMLBL","hangerTop","bottomStrut","midTie",
    "topCross","bottomCross","deckCross",
    "deckLateral","topLateral","bottomLateral","midLateral","sideHoriz"
  ];

  for (let pass = 0; pass < 2; pass++) {
    let changed = false;
    for (const g of groups) {
      if (calls >= MAXCALLS - 5) break;
      const list = cand[g];
      if (!list) continue;
      for (const c of list) {
        if (calls >= MAXCALLS - 2) break;
        const trial = Object.assign({}, p);
        trial[g] = c;
        const r = evalD(trial);
