          p = trial;
          changed = true;
          break; // accept lightest safe for this group
        }
      }
    }
    if (!changed) break;
  }

  // Final verification: if somehow failed, revert to heavy.
  const rFinal = evalD(p);
  if (!rFinal || !isSafe(rFinal, chosenLevel)) {
    p = heavy;
  }

  return build(p);
}

function design(site, analyse) {
  const xs = [0,4.108,8.217,12.325,16.433,20.542,24.65,28.758,32.867,36.975,41.083,45.192,49.3];
  const L = 49.3;
  const RISE = 13.5;
  const ZTOP = 5.65;
  const YMIN = 5.35;

  const topY = i => {
    let y = RISE * 4 * xs[i] * (L - xs[i]) / (L * L);
    return y < YMIN ? YMIN : y;
  };

  const C = s => "S690 CHS" + s;

  const cand = {
    archEnd: [
      C("168.3x6.3"), C("193.7x6.3"), C("193.7x8"), C("219.1x8"),
      C("244.5x8"), C("273x10"), C("323.9x10"), C("355.6x12.5"),
