    ],
    archMid: [
      C("114.3x5"), C("139.7x6.3"), C("168.3x6.3"), C("193.7x6.3"),
      C("193.7x8"), C("219.1x8"), C("244.5x8"), C("273x10"),
      C("323.9x10"), C("355.6x12.5"), C("406.4x12.5")
    ],
    deckChord: [
      C("114.3x5"), C("139.7x6.3"), C("168.3x6.3"), C("193.7x6.3"),
      C("193.7x8"), C("219.1x8"), C("244.5x8"), C("273x10"),
      C("323.9x10"), C("355.6x12.5"), C("406.4x12.5")
    ],
    hanger: [
      C("88.9x5"), C("114.3x5"), C("139.7x6.3"), C("168.3x6.3"),
      C("193.7x6.3"), C("193.7x8"), C("219.1x8"), C("244.5x8"),
      C("273x10"), C("323.9x10")
    ],
    sideDiag: [
      C("139.7x6.3"), C("168.3x6.3"), C("193.7x6.3"), C("193.7x8"),
      C("219.1x8"), C("244.5x8"), C("273x10"), C("323.9x10"),
      C("355.6x12.5"), C("406.4x12.5")
    ],
    sideDiagRev: [
      C("88.9x5"), C("114.3x5"), C("139.7x6.3"), C("168.3x6.3"),
      C("193.7x6.3"), C("193.7x8"), C("219.1x8"), C("244.5x8"),
      C("273x10"), C("323.9x10")
    ],
    deckCross: [
      C("76.1x4"), C("88.9x5"), C("114.3x5"), C("139.7x6.3"),
      C("168.3x6.3"), C("193.7x6.3"), C("193.7x8"), C("219.1x8"),
      C("244.5x8"), C("273x10"), C("323.9x10")
    ],
    topCross: [
      C("76.1x4"), C("88.9x5"), C("114.3x5"), C("139.7x6.3"),
      C("168.3x6.3"), C("193.7x6.3"), C("193.7x8"), C("219.1x8"),
      C("244.5x8"), C("273x10"), C("323.9x10")
    ],
    deckLat: [
      C("76.1x4"), C("88.9x5"), C("114.3x5"), C("139.7x6.3"),
      C("168.3x6.3"), C("193.7x6.3"), C("193.7x8"), C("219.1x8"),
      C("244.5x8"), C("273x10"), C("323.9x10")
    ],
    topLat: [
      C("76.1x4"), C("88.9x5"), C("114.3x5"), C("139.7x6.3"),
      C("168.3x6.3"), C("193.7x6.3"), C("193.7x8"), C("219.1x8"),
      C("244.5x8"), C("273x10"), C("323.9x10")
    ]
  };

  const order = [
    "archEnd", "archMid", "deckChord", "hanger", "sideDiag",
    "sideDiagRev", "deckCross", "topCross", "deckLat", "topLat"
  ];

  function build(p) {
    const nodes = [];
    const members = [];
    const seen = new Set();
    const joints = {};

    function addNode(id, x, y, z, joint) {
      nodes.push({ id: id, x: x, y: y, z: z, joint: joint || "pin" });
    }
    function addMember(a, b, spec) {
      if (!spec || a === b) return;
      const key = a < b ? a + "|" + b : b + "|" + a;
      if (seen.has(key)) return;
      seen.add(key);
      members.push([a, b, spec]);
    }

    for (let i = 1; i <= 11; i++) {
      const y = topY(i);
      addNode("TL" + i, xs[i], y, -ZTOP, "rigid");
      addNode("TR" + i, xs[i], y,  ZTOP, "rigid");
    }

    for (let i = 0; i <= 12; i++) {
      joints["L" + i] = "rigid";
      joints["R" + i] = "rigid";
    }

    // Arch / top chords, from the deck supports through the top nodes.
    for (let side = 0; side < 2; side++) {
      const s = side === 0 ? "L" : "R";
      const t = side === 0 ? "TL" : "TR";
      let prev = s + "0";
      for (let i = 1; i <= 11; i++) {
        const cur = t + i;
        const seg = i - 1;
        const spec = (seg < 2 || seg >= 10) ? p.archEnd : p.archMid;
        addMember(prev, cur, spec);
        prev = cur;
      }
      addMember(prev, s + "12", p.archEnd);
    }

    // Continuous deck edge ties.
    for (let i = 0; i < 12; i++) {
      addMember("L" + i, "L" + (i + 1), p.deckChord);
      addMember("R" + i, "R" + (i + 1), p.deckChord);
    }

    // Outward sloping hangers.
    for (let i = 1; i <= 11; i++) {
      addMember("L" + i, "TL" + i, p.hanger);
      addMember("R" + i, "TR" + i, p.hanger);
    }

    // Side web diagonals: original Warren diagonal plus the reverse diagonal
    // for every internal panel, making an X-braced side truss.
    for (let i = 1; i <= 10; i++) {
      addMember("L" + i, "TL" + (i + 1), p.sideDiag);
      addMember("R" + i, "TR" + (i + 1), p.sideDiag);
      addMember("L" + (i + 1), "TL" + i, p.sideDiagRev);
      addMember("R" + (i + 1), "TR" + i, p.sideDiagRev);
    }

    // Transverse deck and top beams.
    for (let i = 0; i <= 12; i++) {
      addMember("L" + i, "R" + i, p.deckCross);
    }
    for (let i = 1; i <= 11; i++) {
      addMember("TL" + i, "TR" + i, p.topCross);
    }

    // Deck-plane X bracing in every bay.
    for (let i = 0; i < 12; i++) {
      addMember("L" + i, "R" + (i + 1), p.deckLat);
      addMember("R" + i, "L" + (i + 1), p.deckLat);
    }

    // Top-plane X bracing in every internal bay.
    for (let i = 1; i <= 10; i++) {
      addMember("TL" + i, "TR" + (i + 1), p.topLat);
      addMember("TR" + i, "TL" + (i + 1), p.topLat);
    }

    return {
      note: "Deep rigid S690 tied arch with outward hangers and X bracing in the deck, top and side planes.",
      nodes: nodes,
      joints: joints,
      members: members
    };
  }

  const p0 = {};
  for (let g in cand) p0[g] = cand[g][cand[g].length - 1];

  let calls = 0;
  const MAXCALLS = 390;
  const cache = new Map();

  function evaluate(p) {
    const key = JSON.stringify(p);
    if (cache.has(key)) return cache.get(key);
    if (calls >= MAXCALLS) return null;
    calls++;
    let r;
    try {
      r = analyse(build(p));
    } catch (e) {
      r = { error: String(e) };
    }
    cache.set(key, r);
    return r;
  }

  function safe(r, lv) {
    if (!r || r.error || r.ok === false || r.failure) return false;
    if (r.maxUtil != null && r.maxUtil > lv.util) return false;
    const ac = r.alphaCr != null ? r.alphaCr : r.alphaCrMin;
    if (ac != null && ac < lv.alpha) return false;
    const f = r.frequency != null ? r.frequency : r.fMin;
    if (f != null && f < lv.freq) return false;
    const sagLimit = r.sagLimit != null ? r.sagLimit : 164.3;
    if (r.sag != null && r.sag > lv.sag * sagLimit) return false;
    const swayLimit = r.swayLimit != null ? r.swayLimit : 164.3;
    if (r.sway != null && r.sway > lv.sway * swayLimit) return false;
    if (r.fatigueWorst != null && r.fatigueWorst > lv.fatigue) return false;
    if (r.robustness === false) return false;

    if (r.cases) {
      for (let i = 0; i < r.cases.length; i++) {
        const c = r.cases[i];
        if (c && c.maxUtil != null && c.maxUtil > lv.util) return false;
      }
    }
    if (r.members) {
      for (let i = 0; i < r.members.length; i++) {
        const m = r.members[i];
        if (m && m.util != null && m.util > lv.util) return false;
      }
    }
    return true;
  }

  function runLevel(lv) {
    let cur = Object.assign({}, p0);
    let r = evaluate(cur);
    if (!r || !safe(r, lv)) return null;

    for (let pass = 0; pass < 3; pass++) {
      let changed = false;

      for (let oi = 0; oi < order.length; oi++) {
        if (calls >= MAXCALLS - 5) break;
        const g = order[oi];
        const list = cand[g];
        const curSpec = cur[g];
        const curIdx = list.indexOf(curSpec);
        if (curIdx === 0) continue;

        let chosen = null;
        let chosenR = null;

        for (let i = 0; i < list.length; i++) {
          if (curIdx >= 0 && i >= curIdx) break;
          const trial = Object.assign({}, cur);
          trial[g] = list[i];
          const rr = evaluate(trial);
          if (rr && safe(rr, lv)) {
            chosen = list[i];
            chosenR = rr;
            break;
          }
        }

        if (chosen) {
          cur[g] = chosen;
          r = chosenR;
          changed = true;
        }
      }

      if (!changed) break;
    }

    const fin = evaluate(cur);
    if (fin && safe(fin, lv)) return { p: cur, r: fin };
    return null;
  }

  const levels = [
    { util: 0.68, alpha: 6.0, freq: 2.35, sag: 0.75, sway: 0.75, fatigue: 0.70 },
    { util: 0.76, alpha: 5.2, freq: 2.25, sag: 0.86, sway: 0.86, fatigue: 0.82 },
    { util: 0.84, alpha: 4.6, freq: 2.16, sag: 0.95, sway: 0.95, fatigue: 0.94 }
  ];

  let best = null;
  for (let i = 0; i < levels.length; i++) {
    const res = runLevel(levels[i]);
    if (res) {
      best = res;
      break;
    }
    if (calls >= MAXCALLS - 5) break;
  }

  if (!best) {
    const r = evaluate(p0);
    best = { p: p0, r: r };
  }

  const out = build(best.p);
  out.note = "Attempt 5: deep rigid S690 tied arch, outward hangers, X-braced deck/top planes and reverse side diagonals; conservative sizing margins.";
  return out;
}

