    if (!r || r.error || r.ok === false) return false;
    const f = r.failure == null ? "" : String(r.failure).trim().toLowerCase();
    if (f && f !== "none" && f !== "no failure" && f !== "ok" && f !== "pass") return false;

    if (r.maxUtil != null && r.maxUtil > lv.util) return false;

    if (r.members && Array.isArray(r.members)) {
      for (let i = 0; i < r.members.length; i++) {
        const m = r.members[i];
        if (m && m.util != null && m.util > lv.util) return false;
      }
    }

    if (r.cases && Array.isArray(r.cases)) {
      for (let i = 0; i < r.cases.length; i++) {
        const c = r.cases[i];
        if (c && c.maxUtil != null && c.maxUtil > lv.util) return false;
      }
    }

    const ac = r.alphaCr != null ? r.alphaCr : r.alphaCrMin;
    if (ac != null && ac < lv.alpha) return false;

    const fr = r.frequency != null ? r.frequency : r.fMin;
    if (fr != null && fr < lv.freq) return false;

    const sagLim = r.sagLimit != null ? r.sagLimit : 164.3;
    if (r.sag != null && r.sag > lv.sag * sagLim) return false;

    const swayLim = r.swayLimit != null ? r.swayLimit : 164.3;
    if (r.sway != null && r.sway > lv.sway * swayLim) return false;

    if (r.fatigueWorst != null && r.fatigueWorst > lv.fatigue) return false;
    if (r.robustness === false) return false;

    return true;
  }

  const strict   = { util: 0.45, alpha: 7.0, freq: 2.70, sag: 0.55, sway: 0.55, fatigue: 0.50 };
  const moderate = { util: 0.65, alpha: 5.0, freq: 2.25, sag: 0.85, sway: 0.85, fatigue: 0.80 };
  const weak     = { util: 0.82, alpha: 4.15, freq: 2.12, sag: 0.98, sway: 0.98, fatigue: 0.95 };

  for (let i = 0; i < presets.length; i++) {
    const d = build(presets[i]);
    let r;
    try { r = analyse(d); } catch (e) { r = { error: String(e) }; }
    const lv = (i <= 1) ? strict : (i === 2 ? moderate : weak);
    if (safe(r, lv)) return d;
  }

  return build(presets[presets.length - 1]);
}

