        members.push(["TR" + i, "R" + (i + 1), S.d]);
      } else {
        members.push(["TL" + (i + 1), "L" + i, S.d]);
        members.push(["TR" + (i + 1), "R" + i, S.d]);
      }
      // deck-level X bracing (bottom lateral system)
      members.push(["L" + i, "R" + (i + 1), S.ld]);
      members.push(["R" + i, "L" + (i + 1), S.ld]);
