  }

  // Greedy coordinate descent: reduce one group at a time while it still passes
  let improved = true;
  while (improved) {
    improved = false;
    for (let g = 0; g < 6; g++) {
      if (cur.lv[g] <= 0) continue;
      const lv = cur.lv.slice();
      lv[g] -= 1;
      const r = evalLevels(lv);
      if (r && r.ok && r.mass < cur.mass) {
        cur = r;
        improved = true;
      }
    }
  }

  return { note: NOTE, nodes: cur.d.nodes, joints: cur.d.joints, members: cur.d.members };
}

