    const pn = (a, b, s) => ({ a: a, b: b, spec: s, ends: "pin" });
    const members = [];
    for (let i = 0; i < 12; i++) {
      members.push(["L" + i, "L" + (i + 1), sp.bc]);
      members.push(["R" + i, "R" + (i + 1), sp.bc]);
      members.push(["TL" + i, "TL" + (i + 1), sp.tc]);
      members.push(["TR" + i, "TR" + (i + 1), sp.tc]);
      if (i < 6) {
        members.push(pn("TL" + i, "L" + (i + 1), sp.d));
        members.push(pn("TR" + i, "R" + (i + 1), sp.d));
      } else {
        members.push(pn("TL" + (i + 1), "L" + i, sp.d));
        members.push(pn("TR" + (i + 1), "R" + i, sp.d));
      }
      members.push(pn("L" + i, "R" + (i + 1), sp.ld));
      members.push(pn("R" + i, "L" + (i + 1), sp.ld));
      members.push(pn("TL" + i, "TR" + (i + 1), sp.lt));
      members.push(pn("TR" + i, "TL" + (i + 1), sp.lt));
    }
    for (let i = 0; i <= 12; i++) {
      const vs = (i === 0 || i === 12) ? sp.ve : sp.v;
      members.push(["L" + i, "TL" + i, vs]);
      members.push(["R" + i, "TR" + i, vs]);
      members.push(["L" + i, "R" + i, sp.ls]);
      members.push(["TL" + i, "TR" + i, sp.ts]);
    }
    return { note: NOTE, nodes: nodes, joints: joints, members: members };
  }

  function passes(r) {
    if (!r || r.ok !== true) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > 0.8) return false;
    if (typeof r.frequency === "number" && r.frequency < 2.25) return false;
    if (typeof r.alphaCr === "number" && r.alphaCr < 4.5) return false;
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > 0.85) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > 0.85 * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > 0.85 * r.swayLimit) return false;
    return true;
  }

  function ev(H, idx, mat) {
    const key = H + "|" + idx.join(",") + "|" + mat.join(",");
    if (cache[key]) return cache[key];
    if (calls >= limit || calls >= CALL_MAX || timeUp()) return null;
    calls += 1;
    const d = build(H, idx, mat);
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    const res = {
      H: H,
      idx: idx.slice(),
      mat: mat.slice(),
      d: d,
      ok: passes(r),
      mass: (r && typeof r.mass === "number") ? r.mass : Infinity
    };
    cache[key] = res;
    return res;
  }

  function sweep(H, start) {
    let cur = start;
    let changed = true;
    let rounds = 0;
    while (changed && rounds < 8) {
      changed = false;
      rounds += 1;
      for (let g = 0; g < GR.length; g++) {
        const opts = [];
        const i0 = cur.idx[g];
        if (i0 > 0) {
          const a = cur.idx.slice(); a[g] = i0 - 1;
          opts.push([a, cur.mat.slice()]);
        }
        if (!cur.mat[g] && i0 > 0) {
          const a = cur.idx.slice(); a[g] = i0 - 1;
          const m = cur.mat.slice(); m[g] = 1;
          opts.push([a, m]);
        }
        if (!cur.mat[g] && i0 > 1) {
          const a = cur.idx.slice(); a[g] = i0 - 2;
          const m = cur.mat.slice(); m[g] = 1;
          opts.push([a, m]);
        }
        for (const o of opts) {
          const r = ev(H, o[0], o[1]);
          if (!r) return cur;
          if (r.ok && r.mass < cur.mass) { cur = r; changed = true; break; }
        }
      }
      if (timeUp() || calls >= CALL_MAX) break;
    }
    return cur;
  }

  // Start A: attempt-7 design (known to pass). Start B: attempt-5 style indices.
  const A = [20, 20, 22, 20, 18, 18, 18, 21, 21];
  const B = [19, 20, 22, 19, 16, 17, 17, 21, 20];
  const Z9 = [0, 0, 0, 0, 0, 0, 0, 0, 0];
  const STARTS = [[7, A], [7, B], [9, A], [8, A], [10, A]];

  let best = null;
  for (const st of STARTS) {
    if (timeUp() || calls >= CALL_MAX) break;
    limit = Math.min(CALL_MAX, calls + 76);
    const s = ev(st[0], st[1], Z9);
    if (!s || !s.ok) continue;
    const c = sweep(st[0], s);
    if (c.ok && (!best || c.mass < best.mass)) best = c;
  }

  if (best) return best.d;
  return build(7, A, Z9);
}
